<script lang="ts">import type{PageProps}from'./$types';import{rupiah,dateMakassar}from'$lib/format';import Icon from '$lib/Icon.svelte';import CurrencyInput from '$lib/components/CurrencyInput.svelte';let{data,form}:PageProps=$props();let open=$state('');</script>
